export const contentPackClassList = generated.classList;

export type ContentPackClassKey = keyof typeof contentPackClasses;
export type ContentPackClassData = typeof contentPackClasses[ContentPackClassKey];

export function getContentPackClassBySlug(slug: string): ContentPackClassData | null {
	const item = contentPackClassList.find((entry) => entry.slug === slug);
	return item ? contentPackClasses[item.key as ContentPackClassKey] : null;
}

export function getContentPackSubclassBySlug(
	classSlug: string,
	subclassSlug: string
) {
	const classData = getContentPackClassBySlug(classSlug);

	if (!classData) {
		return null;
	}

	return Object.values(classData.subclasses).find((subclass) => {
		const parts = subclass.href.split('/');
		return parts[parts.length - 1] === subclassSlug;
	}) ?? null;
}
